function T(parent,name,chars,style,color,opts={}){
  const t = figma.createText();
  t.name = name;
  if (styles[style]) t.textStyleId = styles[style].id;
  t.fontName = {family:'Roboto', style: opts.weight||'Regular'};
  ;


