// simpler explicit text helper
function text(parent, name, chars, color, size, weight, lh){
  const t = figma.createText();
  t.name = name;
  t.fontName = {family:'Roboto', style: weight||'Regular'};
  t.characters = chars;
  t.fontSize = size;
  t.lineHeight = {unit:'PIXELS', value: lh || Math.round(size*1.35)};
  t.fills = paint(color);
  parent.appendChild(t);
  return t;
}
function box(name, w, h, fill, radius){
  const f = figma.createFrame();
  f.name = name; f.resize(w,h);
  f.fills = fill ? paint(fill) : [];
  f.clipsContent = false;
  if (radius!==undefined) f.cornerRadius = radius;
  return f;
}
function recolor(node, color){
  const targets = node.findAll(n => n.type==='VECTOR' || n.type==='ELLIPSE' || n.type==='RECTANGLE');
  for (const t of targets){ try { t.fills = paint(color); } catch(e){} }
}
async function icon(srcId, size, color){
  const src = await figma.getNodeByIdAsync(srcId);
  const inst = src.createInstance();
  inst.resize(size,size);
  if (color) recolor(inst, color);
  return inst;
}
async function logo(srcId, size){
