async function header(name, kind){
  const c = figma.createComponent();
  c.name = name;
  c.resize(375,56);
  c.fills = [];
  c.layoutMode='HORIZONTAL'; c.primaryAxisSizingMode='FIXED'; c.counterAxisSizingMode='FIXED';
  c.counterAxisAlignItems='CENTER';
  c.paddingLeft=16; c.paddingRight=16;
  c.primaryAxisAlignItems = kind==='detail' ? 'SPACE_BETWEEN' : 'SPACE_BETWEEN';
  if (kind==='back' || kind==='detail'){
    const back = await icon('2:52',24,C.text); c.appendChild(back);
    back.layoutAlign='INHERIT';
  }
  if (kind==='menu'){
    const m = await icon('2:4',24,C.text); c.appendChild(m);
  }
  if (kind==='back' || kind==='detail'){
    const t = text(c,'Title','Top Up',C.text,18,'Semi Bold',24);
    t.layoutGrow=1; t.layoutAlign='INHERIT';
    t.textAlignHorizontal='LEFT';
    if (kind==='detail') t.characters='';
  } else {
    const t = text(c,'Title','Aktivitas',C.text,18,'Semi Bold',24);
    t.layoutGrow=1;
  }
  const right = figma.createFrame();
  right.name='Actions'; right.fills=[]; right.resize(24,24);
  right.layoutMode='HORIZONTAL'; right.primaryAxisSizingMode='AUTO'; right.counterAxisSizingMode='AUTO';
  right.counterAxisAlignItems='CENTER'; right.itemSpacing=16;
  c.appendChild(right);
  if (kind==='menu'){ right.appendChild(await icon('2:7',24,C.text)); }
  if (kind==='back'){ right.appendChild(await icon('2:65',24,C.text2)); }
  if (kind==='detail'){
    right.appendChild(await icon('2:30',24,C.text));
    right.appendChild(await icon('2:58',24,C.text));
    right.appendChild(await icon('2:61',24,C.text));
  }
  root.appendChild(c);
  return c;
}
