async function tabbar(current){
  const c = figma.createComponent();
  c.name = 'Tab Bar · '+TABS.find(t=>t.key===current).label;
  c.resize(375,66);
  c.fills = paint(C.bg);
  c.strokes = [{type:'SOLID', color: rgb(C.border)}];
  c.strokeWeight = 1; c.strokeAlign='INSIDE';
  c.strokes = [];
  c.layoutMode='HORIZONTAL'; c.primaryAxisSizingMode='FIXED'; c.counterAxisSizingMode='FIXED';
  c.primaryAxisAlignItems='SPACE_BETWEEN'; c.counterAxisAlignItems='CENTER';
  c.paddingLeft=8; c.paddingRight=8; c.paddingTop=10;
  for (const tab of TABS){
    const on = tab.key===current;
    const item = box('Tab · '+tab.label, 71, 46, null);
    item.layoutMode='VERTICAL'; item.primaryAxisSizingMode='FIXED'; item.counterAxisSizingMode='FIXED';
    item.primaryAxisAlignItems='CENTER'; item.counterAxisAlignItems='CENTER'; item.itemSpacing=4;
    const ic = await icon(tab.icon, 22, on? C.brand : C.text3);
    if (tab.key==='topup'){
      const wrap = box('Icon Wrap', 30, 26, on? C.brand : C.surface3, 13);
      wrap.layoutMode='HORIZONTAL'; wrap.primaryAxisAlignItems='CENTER'; wrap.counterAxisAlignItems='CENTER';
      wrap.appendChild(await icon('2:30',16, on? '#FFFFFF' : C.text2));
      ic.remove();
      item.appendChild(wrap);
    } else {
      item.appendChild(ic);
    }
    const lb = text(item,'Label',tab.label, on? C.brand : C.text3, 10, on?'Medium':'Regular',13);
    item.appendChild(lb);
    c.appendChild(item);
  }
  root.appendChild(c);
  return c;
}
