function collectText(root){
  const out=[];
  (function walk(n){
    if(n.type==='TEXT'&&typeof n.characters==='string') out.push(n.characters);
    const kids=n.children;
    if(kids) for(const c of Array.from(kids)) walk(c);
  })(root);
  return out.join(' || ');
}
